rx(String.raw`Limit order placed: (Long|Short) ×(\d+) with (${NUM}) when the price reaches ([\d.,]+)\.`, (m, s, l, a, p) => `Orden límite colocada: ${SIDE_ES(s).toLowerCase()} ×${l} con ${a} cuando el precio llegue a ${p}.`);
