hrx(String.raw`Home<small>🌍 Solar System<\/small>`, "Hogar<small>🌍 Sistema Solar</small>");
rx(String.raw`(\d+) of (\d+) ships? free`, (m, a, b) => `${a} de ${b} ${plural(b, "nave libre", "naves libres")}`);
