rx(String.raw`The <b>(${SP_RX_NAME})</b> are now <b>(${SP_RX_LV})</b>! They load a thank-you gift on your ship\.`, (m, n, l) => `¡Los <b>${spN(n)}</b> ya son <b>${spL(l)}</b>! Cargan un regalo de agradecimiento en tu nave.`);
