rx(String.raw`(.+!) Send (\d+) 🔬 scientists within (\d+) minutes \(🚢 Logistics → 🌌 Space\)\.`, (m, x, n, t) => `${spSosEs(x)} Envía ${n} 🔬 científicos en ${t} minutos (🚢 Logística → 🌌 Espacio).`);
