// Turn an item on and turn off other items in the same slot
function turnOn(id) {
  const item = COSMETICS.find(c => c.id === id);
  COSMETICS.forEach(c => { if (c.slot === item.slot) state.cosmetics.on[c.id] = false; });
  state.cosmetics.on[id] = true;
}

