  const hits = wikiSearch(q);
  $("wikiSearchInfo").textContent = hits.length ? `${hits.length}${hits.length === 40 ? "+" : ""} result${hits.length === 1 ? "" : "s"}` : "";
  $("wikiNav").querySelectorAll(".subTab").forEach(b => b.classList.remove("active"));
